                buffer[index] = source[sourceIndex];
                buffer[index + 1] = source[sourceIndex + 1];
                buffer[index + 2] = source[sourceIndex + 2];
                buffer[index + 3] = source[sourceIndex + 3];
            }
        }
        return buffer;
    }

