            links: [
                { from: "noise", fromPort: "out", to: "gradient", toPort: "t" },
                { from: "gradient", fromPort: "out", to: "output", toPort: "color" },
                { from: "noise", fromPort: "out", to: "output", toPort: "bump" },
            ],
