        const ids = new Set();
        for (const raw of graph.nodes.slice(0, 200)) {
            if (!raw || typeof raw.id !== "string" || raw.id.length > 128 || ids.has(raw.id) || !Object.hasOwn(TYPES, raw.type)) continue;
